describe("doctests of sympy.simplify.hyperexpand", () => {
  it("f.lookup_origin(Hyper_Function((), ())).closed_form", () => {
    expect(sympyStr(exp(new Dummy('z', {}, 1000000)))).toBe('exp(_z)');
  });
  it("f.lookup_origin(Hyper_Function([1], ())).closed_form", () => {
    expect(sympyStr(new HyperRep('power1', [-1, new Dummy('z', {}, 1000000)]))).toBe('HyperRep_power1(-1, _z)');
  });
  it("f.lookup_origin(i).closed_form", () => {
    expect(sympyStr(new HyperRep('sqrts1', [rational(-1, 4), new Dummy('z', {}, 1000000)]))).toBe('HyperRep_sqrts1(-1/4, _z)');
  });
  // no value
  //   G_Function(a, b, [2], [y]).compute_buckets()
  //   => ({0: [3, 2, 1], 1/2: [3/2]}, {y: [y, y + 1, y + 3], 0: [2]}, {0: [2]}, {y: [y]})
  it.todo("G_Function(a, b, [2], [y]).compute_buckets()");
  // no value
  //   Hyper_Function(ap, bq).build_invariants()
  //   => (1, ((0, 1), (1/3, 1), (1/2, 2)), ((0, 2),))
  it.todo("Hyper_Function(ap, bq).build_invariants()");
  // no value
  //   op.apply(z**7, lambda f: f.diff(z))
  //   => y*z**7 + 7*z**7 + 42*z**5
  it.todo("op.apply(z**7, lambda f: f.diff(z))");
  it("hyperexpand(hyper([], [], z))", () => {
    const z = new Sym('z');
    expect(sympyStr(hyperexpand(hyper([], [], z)))).toBe('exp(z)');
  });
  it("hyperexpand(1 + hyper([1, 1, 1], [], z))", () => {
    const z = new Sym('z');
    expect(sympyStr(hyperexpand(add(1, hyper([rational(1), rational(1), rational(1)], [], z))))).toBe('hyper((1, 1, 1), (), z) + 1');
  });
  it("reduce_order_meijer(G_Function([3, 4], [5, 6], [3, 4], [1, 2]))[0]", () => {
    expect(sympyStr(new G_Function([4, 3], [5, 6], [3, 4], [2, 1]))).toBe('G_Function((4, 3), (5, 6), (3, 4), (2, 1))');
  });
  it("reduce_order_meijer(G_Function([3, 4], [5, 6], [3, 4], [1, 8]))[0]", () => {
    expect(sympyStr(new G_Function([3], [5, 6], [3, 4], [1]))).toBe('G_Function((3,), (5, 6), (3, 4), (1,))');
  });
  it("reduce_order_meijer(G_Function([3, 4], [5, 6], [7, 5], [1, 5]))[0]", () => {
    expect(sympyStr(new G_Function([3], [], [], [1]))).toBe('G_Function((3,), (), (), (1,))');
  });
  it("reduce_order_meijer(G_Function([3, 4], [5, 6], [7, 5], [5, 3]))[0]", () => {
    expect(sympyStr(new G_Function([], [], [], []))).toBe('G_Function((), (), (), ())');
  });
  it("devise_plan(Hyper_Function((1, 2), ()), Hyper_Function((1, 2), ()), z)", () => {
    expect(sympyStr([])).toBe('[]');
  });
  it("devise_plan(Hyper_Function((), (1, 2)), Hyper_Function((), (1, 2)), z)", () => {
    expect(sympyStr([])).toBe('[]');
  });
  it("devise_plan_meijer(G_Function([1], [2], [3], [4]),", () => {
    expect(sympyStr([])).toBe('[]');
  });
  it("reduce_order(Hyper_Function((1, 2), (3, 4)))", () => {
    expect(sympyMatches([at(reduceOrder(new Hyper_Function([1, 2], [3, 4])), 0), []], '(Hyper_Function((1, 2), (3, 4)), [])')).toBe(true);
  });
});

